sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var tableName;
    if (event.elementId == 'content_tree_1') {
        tableName = 'sn_risk_definition';
    } else if (event.elementId == 'content_tree_2') {
        tableName = 'sn_risk_advanced_basel_category';
    } else {
        tableName = 'sn_risk_advanced_basel_business_line';
    }
    const payload = {
        route: 'record',
        fields: {
            table: tableName,
            sysId: event.payload.item.id
        }
    };
    const {
        emit
    } = api;
    emit('NAV_ITEM_SELECTED', payload);
}
